+
+        CompactingArrayManager(Class<T> elementType) {
+            super(elementType);
+        }
+
+        @Override
+        protected int compact(ListenerListBase instance, T[] array) {
+            if (instance.isLocked()) {
+                return 0;
+            }
+
+            int shift = 0;
+
+            for (int i = 0; i < array.length; i++) {
+                T element = array[i];
