+        }
+
+        @Override
+        protected int getOccupiedSlots(ListenerListBase instance) {
+            return instance.invalidationListenersCount;
+        }
+
+        @Override
+        protected void setOccupiedSlots(ListenerListBase instance, int occupiedSlots) {
